Bash(node -e "
const {execSync}=require\('child_process'\);
const tickers = ['AGS.SI','H02.SI','BS6.SI','F34.SI','V03.SI','CHZ.SI','E28.SI','AWX.SI','S68.SI','BSL.SI','5WH.SI','M05.SI','Q01.SI','B16.SI','G13.SI','C52.SI','D05.SI','Z74.SI','F99.SI','CJL.SI'];
const results = {};
for\(const t of tickers\) {
  try {
    const r=execSync\('curl -s -H \\"User-Agent: Mozilla/5.0\\" \\"https://query1.finance.yahoo.com/v8/finance/chart/'+t+'?interval=1d&range=1y\\"', {timeout: 15000}\);
    const d=JSON.parse\(r.toString\(\)\);
    if\(d.chart && d.chart.result\) {
      const m=d.chart.result[0].meta;
      results[t] = {
        name: m.longName || m.shortName || t,
        price: m.regularMarketPrice,
        currency: m.currency,
        high52: m.fiftyTwoWeekHigh,
        low52: m.fiftyTwoWeekLow,
        dayHigh: m.regularMarketDayHigh,
        dayLow: m.regularMarketDayLow,
        volume: m.regularMarketVolume,
        prevClose: m.chartPreviousClose
      };
    } else { results[t] = {error:'no result', raw: r.toString\(\).substring\(0,100\)}; }
  } catch\(e\) { results[t] = {error: e.message}; }
}
console.log\(JSON.stringify\(results, null, 2\)\);
" 2>&1)

